CREATE TABLE IF NOT EXISTS roupa (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, tipo VARCHAR(120) NOT NULL, cor VARCHAR(80) NOT NULL, preco DECIMAL(10,2) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS manequim (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, material VARCHAR(120) NOT NULL, cor VARCHAR(80) NOT NULL, roupa VARCHAR(120) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS loja (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, endereco VARCHAR(240) NOT NULL, quantidade_funcionarios INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ciclista (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, nivel VARCHAR(80) NOT NULL, velocidade DECIMAL(8,2) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bicicleta (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, marca VARCHAR(120) NOT NULL, aro INT NOT NULL, tipo_freio VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS trilha (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, distancia DECIMAL(8,2) NOT NULL, dificuldade VARCHAR(80) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mascara (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, origem VARCHAR(120) NOT NULL, material VARCHAR(120) NOT NULL, estilo VARCHAR(120) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS colecionador (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, quantidade_pecas INT NOT NULL, especialidade VARCHAR(160) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exposicao (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, local VARCHAR(160) NOT NULL, quantidade_mascaras INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cliente (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, telefone VARCHAR(40) NOT NULL, tipo_cabelo VARCHAR(100) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS corte (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, estilo VARCHAR(120) NOT NULL, comprimento VARCHAR(80) NOT NULL, preco DECIMAL(10,2) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cabeleireiro (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, especialidade VARCHAR(160) NOT NULL, anos_experiencia INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
